export interface Post {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
}

import { unstable_cache } from 'next/cache';
import { Post } from './types';

const posts: Post[] = [];

export async function getPosts(): Promise<Post[]> {
  const cachedPosts = unstable_cache(
    async () => {
      return posts;
    },
    ['posts-list'],
    {
      tags: ['posts'],
      revalidate: 3600,
    }
  );

  return cachedPosts();
}

export async function createPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date(),
  };

  posts.push(post);
  return post;
}

'use server';

import { revalidateTag } from 'next/cache';
import { createPost } from '@/lib/data';

export async function createPostAction(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  await createPost(title, content);

  revalidateTag('posts');
}

import { getPosts } from '@/lib/data';
import Link from 'next/link';

export default async function PostsPage() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Posts</h1>
      <Link href="/posts/new">
        <button>Create New Post</button>
      </Link>

      <div style={{ marginTop: '2rem' }}>
        {posts.length === 0 ? (
          <p>No posts yet.</p>
        ) : (
          posts.map((post) => (
            <article key={post.id} style={{ marginBottom: '1rem', padding: '1rem', border: '1px solid #ccc' }}>
              <h2>{post.title}</h2>
              <p>{post.content}</p>
              <small>{post.createdAt.toLocaleString()}</small>
            </article>
          ))
        )}
      </div>
    </main>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { createPostAction } from '../actions';

export default function NewPostPage() {
  const router = useRouter();

  async function handleSubmit(formData: FormData) {
    await createPostAction(formData);
    router.push('/posts');
  }

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Create New Post</h1>
      <form action={handleSubmit}>
        <div style={{ marginBottom: '1rem' }}>
          <label htmlFor="title">Title:</label>
          <input 
            type="text" 
            id="title" 
            name="title" 
            required 
            style={{ display: 'block', width: '100%', padding: '0.5rem' }}
          />
        </div>
        <div style={{ marginBottom: '1rem' }}>
          <label htmlFor="content">Content:</label>
          <textarea 
            id="content" 
            name="content" 
            required 
            rows={5}
            style={{ display: 'block', width: '100%', padding: '0.5rem' }}
          />
        </div>
        <button type="submit">Create Post</button>
      </form>
    </main>
  );
}

import Link from 'next/link';

export default function Home() {
  return (
    <main style={{ padding: '2rem' }}>
      <h1>Posts</h1>
      <p>Welcome to the posts app!</p>
      <Link href="/posts">
        <button>View Posts</button>
      </Link>
    </main>
  );
}

